import os
import torch


class Config:
    # -----------------------------
    # General Configuration
    # -----------------------------
    SEED = 42
    DEBUG = False  # Set to True to use a subset of data for debugging
    DEBUG_SAMPLE_SIZE = 100  # Number of samples to use in debug mode

    # -----------------------------
    # Data Paths
    # -----------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    IMAGES_DIR = os.path.join(INPUT_DIR, "images")

    # Metadata files generated by the provided script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # -----------------------------
    # Output Paths
    # -----------------------------
    WORKING_DIR = "./working"
    IDEA_DIR = os.path.join(WORKING_DIR, "idea_2")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # -----------------------------
    # Model Configuration
    # -----------------------------
    MODEL_NAME = "tf_efficientnet_b4"
    NUM_CLASSES = 4
    # Columns in order: healthy, multiple_diseases, rust, scab
    CLASS_LABELS = ["healthy", "multiple_diseases", "rust", "scab"]
    PRETRAINED = True
    DROPOUT_RATE = 0.4

    # -----------------------------
    # Training Configuration
    # -----------------------------
    IMAGE_SIZE = 380
    BATCH_SIZE = 16  # Fits A100 comfortably with B4 @ 380px
    EPOCHS = 20
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-6
    LABEL_SMOOTHING = 0.1
    MAX_GRAD_NORM = 10.0

    # Scheduler (Cosine Annealing)
    T_MAX = 20
    MIN_LR = 1e-6

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # -----------------------------
    # Augmentation Configuration
    # -----------------------------
    # CoarseDropout parameters for information dropping strategy
    COARSE_DROPOUT_MAX_HOLES = 8
    COARSE_DROPOUT_MAX_HEIGHT = 120
    COARSE_DROPOUT_MAX_WIDTH = 120
    COARSE_DROPOUT_MIN_HOLES = 1
    COARSE_DROPOUT_MIN_HEIGHT = 16
    COARSE_DROPOUT_MIN_WIDTH = 16

    @classmethod
    def setup_directories(cls):
        """Creates necessary output directories."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.IDEA_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
